document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("statRecords"),e=document.getElementById("statCountries"),n=document.getElementById("statCategories");t&&e&&n&&(t.dataset.count=IRWR_RECORDS.length,e.dataset.count=new Set(IRWR_RECORDS.map(t=>t.country)).size,n.dataset.count=IRWR.CATEGORIES.length,IRWR.initCounters(".statrow .num"))});